package android.view.animation;import android.view.View;public class Animation {public long duration;public AnimationListener listener;public interface AnimationListener{void onAnimationStart(Animation a);void onAnimationEnd(Animation a);void onAnimationRepeat(Animation a);}public void setDuration(long d){duration=d;}public void setAnimationListener(AnimationListener l){listener=l;}public void start(View v){if(listener!=null)listener.onAnimationStart(this);rv.batch.Platform.invoke("view.animation",v,this);rv.batch.Platform.post(()->{if(listener!=null)listener.onAnimationEnd(this);},duration,true);}}
